use std::thread;

let textes = vec!["a b a", "b c", "a"];
let hs: Vec<_> = textes.into_iter()
    .map(|t| thread::spawn(move || {
        t.split(' ').filter(|m| *m == "a").count()
    }))
    .collect();
let total: usize = hs.into_iter()
    .map(|h| h.join().unwrap()).sum();
println!("{total}");
